record R(int X, int Y = 2) {
 public int X { get; init; } = Trace("X", X + 1);
 public int Total { get; } = Trace("Total", X + Y);
 public R() : this(3) { Print("outer"); }
 static int Trace(string label, int n) { Print(label + ":" + n); return n; }
}
void Main() {
 var r = new R(); Print(r.X); Print(r.Total);
 var c = r with { X = 9 }; Print(c.X); Print(c.Total); Print(r.X);
}
